Here's a complete implementation:

## XAML

```xml
<ContentPage xmlns="http://schemas.microsoft.com/dotnet/2021/maui"
             xmlns:x="http://schemas.microsoft.com/winfx/2009/xaml"
             xmlns:vm="clr-namespace:MyApp.ViewModels"
             xmlns:models="clr-namespace:MyApp.Models"
             x:Class="MyApp.Views.ItemsPage"
             x:DataType="vm:ItemsViewModel">

    <RefreshView IsRefreshing="{Binding IsRefreshing}"
                 Command="{Binding RefreshCommand}">
        <CollectionView ItemsSource="{Binding Items}"
                        SelectionMode="Single"
                        SelectedItem="{Binding SelectedItem, Mode=TwoWay}"
                        SelectionChangedCommand="{Binding ItemSelectedCommand}">
            <CollectionView.ItemTemplate>
                <DataTemplate x:DataType="models:Item">
                    <Grid Padding="12" ColumnDefinitions="Auto,*">
                        <Image Source="{Binding Icon}" WidthRequest="40" HeightRequest="40" />
                        <Label Grid.Column="1" Text="{Binding Name}" VerticalOptions="Center" />
                    </Grid>
                </DataTemplate>
            </CollectionView.ItemTemplate>
            <CollectionView.EmptyView>
                <Label Text="No items found." HorizontalOptions="Center" VerticalOptions="Center" />
            </CollectionView.EmptyView>
        </CollectionView>
    </RefreshView>
</ContentPage>
```

## ViewModel

```csharp
using CommunityToolkit.Mvvm.ComponentModel;
using CommunityToolkit.Mvvm.Input;
using System.Collections.ObjectModel;

public partial class ItemsViewModel : ObservableObject
{
    private readonly IApiService _api;

    [ObservableProperty]
    private bool isRefreshing;

    [ObservableProperty]
    private Item? selectedItem;

    public ObservableCollection<Item> Items { get; } = new();

    public ItemsViewModel(IApiService api)
    {
        _api = api;
    }

    [RelayCommand]
    private async Task Refresh()
    {
        var data = await _api.GetItemsAsync();
        Items.Clear();
        foreach (var item in data)
            Items.Add(item);
        IsRefreshing = false; // signals RefreshView to stop spinner
    }

    [RelayCommand]
    private async Task ItemSelected()
    {
        if (SelectedItem is null) return;

        await Shell.Current.GoToAsync($"detail?id={SelectedItem.Id}");
        SelectedItem = null; // reset so user can re-select same item
    }
}
```

## Key Bindings Explained

| Property | Purpose |
|---|---|
| `RefreshView.IsRefreshing` → `IsRefreshing` | Controls the spinner; set `false` when done |
| `RefreshView.Command` → `RefreshCommand` | Triggered on pull-down gesture |
| `SelectionMode="Single"` | Enables single-tap selection |
| `SelectedItem` → `SelectedItem` (TwoWay) | Tracks current selection |
| `SelectionChangedCommand` → `ItemSelectedCommand` | Fires on selection change for navigation |

**Important details:**
- Use `ObservableCollection<T>` (not `List<T>`) so UI updates automatically.
- Set `SelectedItem = null` after navigation so the same item can be re-selected.
- Set `IsRefreshing = false` at the end of `Refresh()` to dismiss the spinner.
- Use `x:DataType` on both the page and the `DataTemplate` for compiled bindings.
